#include <bits/stdc++.h>
using namespace std;

struct DSU {
    vector<int> parent, size;
    void initialize(int n) {
        parent.resize(n);
        size.resize(n);
        for (int i = 0; i < n; ++i) {
            parent[i] = i;
            size[i] = 1;
        }
    }
    int find_parent(int x) {
        if (parent[x] != x) parent[x] = find_parent(parent[x]);
        return parent[x];
    }
    void union_sets(int a, int b) {
        a = find_parent(a);
        b = find_parent(b);
        if (a != b) {
            if (size[a] < size[b]) swap(a, b);
            parent[b] = a;
            size[a] += size[b];
        }
    }
};

long long mod_exp(long long base, int exp, int mod) {
    long long res = 1;
    while (exp > 0) {
        if (exp & 1) res = (res * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, k;
    cin >> n >> k;
    const int MOD = 1e9 + 7;
    if (k == 0) {
        cout << mod_exp(n, n - 1, MOD) << "\n";
        return 0;
    }
    DSU dsu;
    dsu.initialize(n);
    for (int i = 0; i < n; ++i) {
        dsu.union_sets(i, (long long)i * k % n);
    }
    long long total = 1;
    for (int i = 0; i < n; ++i) {
        if (dsu.find_parent(i) != i) continue;
        long long t = mod_exp(k, dsu.size[dsu.find_parent(i)], n);
        if (t == 1) {
            total = (total * n) % MOD;
        }
    }
    cout << total << "\n";
}
